import 'dart:convert';
import 'package:http/http.dart' as http;
import 'classUser.dart';

class UserService {
  final http.Client client;

  /// Crea un UserService. Si no se proporciona un [client], se crea uno por defecto.
  UserService({http.Client? client}) : client = client ?? http.Client();

  // Convierte la respuesta JSON en una lista de User
  List<User> parseUsers(String responseBody) {
    final Map<String, dynamic> decodedJson = jsonDecode(responseBody);
    final List<dynamic> userListJson = decodedJson['data'];
    return userListJson
        .map((json) => User.fromJson(json as Map<String, dynamic>))
        .toList();
  }

  // Obtiene usuarios desde la API REST
  Future<List<User>> fetchUsers() async {
    const String url = 'https://reqres.in/api/users?page=1';
    try {
      final response = await client.get(Uri.parse(url));
      if (response.statusCode == 200) {
        return parseUsers(response.body);
      } else {
        throw Exception(
            'Failed to load users. Status code: ${response.statusCode}');
      }
    } catch (e) {
      throw Exception('Error fetching users: $e');
    }
  }
}
